-- Per-user saved study packs generated by ULTRON.
-- This migration is source-only until explicitly applied in the target Supabase project.

create table if not exists public.study_packs (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  title text not null check (char_length(title) between 1 and 200),
  topic text not null check (char_length(topic) between 1 and 1200),
  format text not null check (format in ('mixed', 'flashcards', 'quiz', 'revision_sheet')),
  level text not null check (level in ('beginner', 'intermediate', 'advanced', 'exam')),
  language text not null default 'English' check (char_length(language) between 1 and 60),
  source_mode text not null check (source_mode in ('general_knowledge_draft', 'based_on_user_supplied_content')),
  content jsonb not null check (
    jsonb_typeof(content) = 'object'
    and pg_column_size(content) <= 60000
  ),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists study_packs_user_created_idx
  on public.study_packs (user_id, created_at desc);

alter table public.study_packs enable row level security;

drop policy if exists study_packs_select_own on public.study_packs;
create policy study_packs_select_own on public.study_packs
  for select to authenticated
  using (user_id = (select auth.uid()));

drop policy if exists study_packs_insert_own on public.study_packs;
create policy study_packs_insert_own on public.study_packs
  for insert to authenticated
  with check (user_id = (select auth.uid()));

drop policy if exists study_packs_update_own on public.study_packs;
create policy study_packs_update_own on public.study_packs
  for update to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

drop policy if exists study_packs_delete_own on public.study_packs;
create policy study_packs_delete_own on public.study_packs
  for delete to authenticated
  using (user_id = (select auth.uid()));

drop trigger if exists study_packs_set_updated_at on public.study_packs;
create trigger study_packs_set_updated_at
  before update on public.study_packs
  for each row execute function public.ultron_set_updated_at();

-- User JWTs and RLS enforce row ownership; no anonymous/public access or server-role key is needed.
revoke all on table public.study_packs from public, anon, authenticated;
grant select, insert, update, delete on table public.study_packs to authenticated;
